<?php
include '../db_connect.php';
$payment_id = isset($_GET['id']) ? (int)$_GET['id'] : 0;
$order = $conn->query("SELECT a.*, b.supp_name AS suppName, u.name AS receiverName FROM supplier_payment AS a INNER JOIN suppliers AS b ON a.supplier_id = b.supp_id LEFT JOIN users AS u ON a.user_id = u.id WHERE a.pay_id = {$payment_id} LIMIT 1");
if(!$order || !$order->num_rows){ echo '<div class="supplier-payment-empty">Payment record not found.</div>'; return; }
$payment = $order->fetch_assoc();
function supplier_payment_value($value, $fallback = '-'){$value = trim((string)$value);return htmlspecialchars($value !== '' ? $value : $fallback, ENT_QUOTES, 'UTF-8');}
$pay_mode = ((int)$payment['payment_mode'] === 1) ? 'Cash' : 'Cheque';
$pay_code = 'SPAY-'.str_pad((int)$payment['pay_id'], 6, '0', STR_PAD_LEFT);
$payment_date_text = date('d M Y', strtotime($payment['payment_date']));
$cheque_date_text = !empty($payment['cheque_date']) && $payment['cheque_date'] !== '0000-00-00' ? date('d M Y', strtotime($payment['cheque_date'])) : '-';
?>
<style>
